package com.vaijunto.controller;
import com.vaijunto.dto.*; import com.vaijunto.service.VehicleService; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/vehicles") @RequiredArgsConstructor public class VehicleController {private final VehicleService service; @GetMapping public List<VehicleDto> list(Authentication a){return service.list(a.getName());}@PostMapping public ResponseEntity<VehicleDto> create(@RequestBody VehicleRequest r,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r,a.getName()));}@PutMapping("/{id}") public VehicleDto update(@PathVariable UUID id,@RequestBody VehicleRequest r,Authentication a){return service.update(id,r,a.getName());}@PostMapping("/{id}/default") public VehicleDto defaultVehicle(@PathVariable UUID id,Authentication a){return service.makeDefault(id,a.getName());}@DeleteMapping("/{id}") public ResponseEntity<Void> archive(@PathVariable UUID id,Authentication a){service.archive(id,a.getName());return ResponseEntity.noContent().build();}}
